def _apply_native_sticky(result):
    if not result:
        return result
    values = list(result) if isinstance(result, (tuple, list)) else [result]
    if not values:
        return result
    columns = values[0] or []
    for index, column in enumerate(columns):
        if isinstance(column, dict):
            column["sticky"] = bool(index < 2)
    values[0] = columns
    return tuple(values)

def execute(filters=None):
    local_vars={"filters":filters or {}}
    safe_exec(REPORT_SCRIPT,None,local_vars,script_filename='Compliance Assurance')
    return finalize_report_result(local_vars.get("data") or ([], []))
